// Enhanced batch approval with audit logging and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"strings"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Compute requestHash for the given IDs
		requestHash := computeRequestHash(ids)

		// Check for existing ActionRequest with same key in this scope
		var existingHash string
		var existingResponse []byte
		err = tx.QueryRow(ctx, 
			`SELECT "requestHash", response FROM "ActionRequest" 
			 WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, operation, key).Scan(&existingHash, &existingResponse)

		if err == nil {
			// ActionRequest exists - check if it's a replay (same hash) or conflict (different hash)
			if existingHash == requestHash {
				// Replay: same key, same targets
				var result protocol.Result
				err = json.Unmarshal(existingResponse, &result)
				if err != nil {
					return protocol.Result{}, false, err
				}
				return result, true, nil
			} else {
				// Conflict: same key, different targets
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// No existing ActionRequest - proceed with approval
		// Lock and fetch eligible purchases
		rows, err := tx.Query(ctx, 
			`SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, 
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All requested IDs must be eligible (exist, match criteria)
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update Purchase status
		tag, err := tx.Exec(ctx, 
			`UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, 
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create ActionRequest record
		responseJSON, _ := json.Marshal(protocol.Result{ApprovedIDs: ids})
		err = tx.QueryRow(ctx,
			`INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response)
			 VALUES ($1, $2, $3, $4, $5, $6)
			 ON CONFLICT DO NOTHING
			 RETURNING key`,
			u.Tenant, u.User, operation, key, requestHash, responseJSON).Scan()

		// ON CONFLICT DO NOTHING means if someone else inserted concurrently, we won't see a row
		// This is acceptable for concurrent inserts with same key+collection
		if err != nil && err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// Insert ApprovalAudit records for each approved purchase
		for _, id := range ids {
			_, err := tx.Exec(ctx,
				`INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
				u.Tenant, id, u.User, operation, key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: ids}, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

// computeRequestHash computes SHA-256 of "bulk-approve.v3\n" + formatted IDs
func computeRequestHash(ids []string) string {
	h := sha256.New()
	h.Write([]byte(operation))
	h.Write([]byte("\n"))

	for _, id := range ids {
		// Format: <UTF-8 byte length>:<ID>
		idBytes := []byte(id)
		h.Write([]byte(fmt.Sprintf("%d:", len(idBytes))))
		h.Write(idBytes)
	}

	return hex.EncodeToString(h.Sum(nil))
}

