	 VALUES ($1, $2, $3, $4, $5, $6)
	 ON CONFLICT DO NOTHING
	 RETURNING key`,
	u.Tenant, u.User, operation, key, requestHash, responseJSON).Scan()

if err == pgx.ErrNoRows {
	// Concurrent insertion - someone else already inserted this ActionRequest
	// Since we got here after successful approval update, this is unexpected
	// Return an error that will be handled as 503
	return protocol.Result{}, false, fmt.Errorf("concurrent action insertion")
} else if err != nil {
	return protocol.Result{}, false, err
}

// Insert ApprovalAudit records for each approved purchase
for _, id := range ids {
	_, err := tx.Exec(ctx,
		`INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
		 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		u.Tenant, id, u.User, operation, key, "submitted", "approved")
	if err != nil {
		return protocol.Result{}, false, err
	}
}

